DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`igangaschool`@`localhost` PROCEDURE `get_dashboard_statistics` (IN `p_user_id` INT, IN `p_role` VARCHAR(100))   BEGIN
    SELECT
        (SELECT COUNT(*) FROM igangaschool_staffs.staff WHERE status='Active') AS total_staff,
        (SELECT COUNT(*) FROM igangaschool_students.students WHERE status='Active') AS total_students,
        0 AS pending_applications,
        2 AS active_programs,
        0 AS total_revenue,
        0 AS total_expenses;
END$$

CREATE DEFINER=`igangaschool`@`localhost` PROCEDURE `get_staff_performance_summary` (IN `p_user_id` INT)   BEGIN
    SELECT s.id, s.full_name, sr.role_name, s.department, s.status,
           0 AS performance_score, 'Good' AS rating
    FROM staff s
    LEFT JOIN staff_roles sr ON s.role_id = sr.id
    WHERE s.status = 'Active'
    ORDER BY s.full_name
    LIMIT 20;
END$$

DELIMITER ;

